private val gunKeys=listOf("NeonGrid","CrimsonCircuit","AzureVault","MagentaMaze","GoldenCore","ObsidianRift","SolarFlare","QuantumAbyss","StormCitadel","CelestialForge")
private val palettes=listOf(listOf("#2defff","#ff4196","#ffc753","#070a16","#5e7896","#16233a"),listOf("#4bff96","#ff694b","#dcff5a","#051212","#5a927f","#11322f"),listOf("#b482ff","#ff5abe","#ffbe64","#0d0719","#8470a5","#29193f"),listOf("#ff735a","#ff4155","#ffd166","#170708","#a66d73","#3d1920"),listOf("#ffbd4a","#ff774d","#fff07a","#170e05","#aa8558","#3d2b13"),listOf("#50c8ff","#5a8cff","#a3e7ff","#06101b","#718ca6","#142a40"))
private data class Hazard(val type:String,val x:Double,val y:Double,val width:Double,val height:Double)
private data class Stage(val id:Int,val name:String,val maxBounces:Int,val hazards:List<Hazard>)
private data class Enemy(var x:Double,var y:Double,var alive:Boolean=true,val kind:Int=0,var hp:Int=1,var fireCooldown:Double=1.6,val canSplit:Boolean=true,var jumpTime:Double=0.0,var jumpCooldown:Double=1.4,var shieldHits:Int=0,var maxHp:Int=hp,var hitCooldown:Double=0.0)
private data class Gun(var angle:Double=0.0,var cooldown:Double=0.35,var flash:Double=0.0,var target:Int=-1,var tx:Double=0.0,var ty:Double=0.0,var mx:Double=0.0,var my:Double=0.0)
private data class Pickup(val type:String,val x:Double,val y:Double,var active:Boolean=true)
private data class Particle(var x:Double,var y:Double,var vx:Double,var vy:Double,var life:Double,val color:String,val radius:Double)
private data class Upgrade(val id:String,val title:String,val description:String,val cost:Int,val max:Int,val icon:String)
private val upgrades=listOf(Upgrade("nova","NOVA PULSE","Shockwave around the blade",350,1,"Effects & Particles/Explosion.png"),Upgrade("overdrive","BLADE OVERDRIVE","Faster blade rebounds",300,2,"Gameplay Sprites/Blade.png"),Upgrade("shield_mod","SHIELD EXTENDER","A wider safety shield",250,2,"UI Elements/UI Panel.png"),Upgrade("pulse_core","PULSE CORE","Wider pulse, shorter cooldown",250,2,"UI Elements/Combo Icon.png"),Upgrade("coin_magnet","COIN MAGNET","More coins per cleared level",400,2,"UI Elements/Star Icon.png"))
private lateinit var canvas:HTMLCanvasElement
private lateinit var g:CanvasRenderingContext2D
private var w=960.0;private var h=540.0;private var m=540.0
private var screen="menu";private var shopReturn="menu";private var levelId=1;private var selectedWorld=0;private var difficulty=2;private var theme=0;private var selectedGun=0;private var mode="campaign"
private var leftHanded=false;private var sound=true;private var reducedMotion=false;private var dynamicDifficulty=true;private var unlocked=1;private var coins=0;private var score=0;private var combo=0;private var bestCombo=0;private var comboWindow=0.0;private var elapsed=0.0;private var starsEarned=0;private var coinsEarned=0
private var animationTime=0.0;private var lastFrame=0.0;private var guardY=0.5;private var bladeX=0.145;private var bladeY=0.5;private var vx=0.0;private var vy=0.0;private var bladeAngle=0.0;private var flying=false;private var slow=false;private var slowMeter=1.0
private var messageText="";private var messageTime=0.0;private var impactTime=0.0;private var impactX=0.0;private var impactY=0.0;private var novaCooldown=0.0;private var novaFlash=0.0;private var novaX=0.0;private var novaY=0.0;private var novaRadius=0.0;private var teleportCooldown=0.0;private var extraLifeUsed=false;private var multiCatch=0
private var switchActivated=false;private var keyCollected=false;private var music:dynamic=null;private var musicPath=""
private val enemies=mutableListOf<Enemy>();private val pickups=mutableListOf<Pickup>();private val particles=mutableListOf<Particle>();private val trail=mutableListOf<Pair<Double,Double>>();private val hazardsCollected=mutableSetOf<Int>();private val effects=mutableMapOf<String,Double>();private val guns=mutableListOf(Gun(),Gun());private val stages=mutableListOf<Stage>();private val images=mutableMapOf<String,HTMLImageElement>();private val audio=mutableMapOf<String,dynamic>();private val pointers=mutableMapOf<Int,Pair<Double,Double>>()
private var primaryPointer=-1;private var storyPage=0

private fun pref(k:String,d:String)=try{window.localStorage.getItem("bounce_blade_"+k)?:d}catch(_:Throwable){d}
private fun put(k:String,v:String){try{window.localStorage.setItem("bounce_blade_"+k,v)}catch(_:Throwable){}}
private fun intPref(k:String,d:Int)=pref(k,d.toString()).toIntOrNull()?:d
private fun boolPref(k:String,d:Boolean)=pref(k,d.toString()).toBooleanStrictOrNull()?:d
private fun persist(){put("unlocked_level",unlocked.toString());put("coins",coins.toString());put("difficulty_stars",difficulty.toString());put("theme_id",theme.toString());put("player_minigun",selectedGun.toString());put("left_handed",leftHanded.toString());put("sound_enabled",sound.toString());put("dynamic_difficulty",dynamicDifficulty.toString())}
private fun palette()=palettes[theme.coerceIn(0,5)]
private fun cyan()=palette()[0]
private fun pink()=palette()[1]
private fun gold()=palette()[2]
private fun dark()=palette()[3]
private fun muted()=palette()[4]
private fun grid()=palette()[5]
private fun clamp(v:Double,a:Double,b:Double)=v.coerceIn(a,b)
private fun dist2(x1:Double,y1:Double,x2:Double,y2:Double):Double{val dx=x1-x2;val dy=y1-y2;return dx*dx+dy*dy}
private fun normAngle(deg:Double):Double{var a=(deg+180.0)%360.0;if(a<0)a+=360.0;return a-180.0}
private fun worldOf(id:Int)=((id.coerceIn(1,TOTAL)-1)/10).coerceIn(0,9)
private fun starCount(id:Int)=intPref("stars_$"+"$"+"id",0).coerceIn(0,3)
private fun scoreBest(id:Int)=intPref("score_$"+"$"+"id",0)
private fun upgradeLevel(id:String)=intPref("upgrade_$"+"$"+"id",0).coerceAtLeast(0)
private fun cost(item:Upgrade)=item.cost*(upgradeLevel(item.id)+1)
private fun gunUnlocked(i:Int)=i==0||boolPref("player_minigun_unlocked_$"+"$"+"i",false)
private fun gunIndex()=if(gunUnlocked(selectedGun))selectedGun else 0
private fun droneDamage(e:Enemy)=((e.maxHp.coerceAtLeast(1)+2)/3).coerceAtLeast(1)
private fun enemyKind(id:Int,index:Int):Int{if(id<=50)return when(id){in 1..20->0;in 21..30->1;in 31..40->2;else->3};val roster=when(id){in 51..60->listOf(8,4,0,3);in 61..70->listOf(5,0,8,1);in 71..80->listOf(6,0,2,3);in 81..90->listOf(7,1,5,8);else->listOf(8,4,5,6,7,9)};return roster[index%roster.size]}
private fun enemyHealth(id:Int,i:Int):Int=when{id in 91..100->5+i%3;id in 51..90->if(i%4==0)4 else 2;id in 21..30||id>=41->3;else->1}
private fun readStageData(){
    stages.clear()
    try{val all:dynamic=js("window.LEVEL_DATA");val n=(all.length as Number).toInt()
        for(i in 0 until n){val d=all[i];val hs=mutableListOf<Hazard>();val arr=d.hazards
            if(arr!=null&&jsTypeOf(arr.length)!="undefined"){val count=(arr.length as Number).toInt();for(j in 0 until count){val z=arr[j];hs.add(Hazard(z.type?.toString()?.lowercase()?:"spikes",(z.x as? Number)?.toDouble()?:0.5,(z.y as? Number)?.toDouble()?:0.5,(z.width as? Number)?.toDouble()?:0.2,(z.height as? Number)?.toDouble()?:0.03))}}
            stages.add(Stage((d.id as Number).toInt(),d.name?.toString()?:("Level "+(i+1)),(d.maxBounces as? Number)?.toInt()?:8,hs))
        }
    }catch(_:Throwable){}
    if(stages.isEmpty())for(i in 1..TOTAL)stages.add(Stage(i,worlds[worldOf(i)]+" "+((i-1)%10+1),8+(i-1)/5,emptyList()))
}
private fun img(path:String):HTMLImageElement{var image=images[path];if(image==null){image=document.createElement("img") as HTMLImageElement;image.src="assets/Images/"+path;images[path]=image};return image}
private fun drawAsset(path:String,x:Double,y:Double,bw:Double,bh:Double,alpha:Double=1.0){if(bw<=0||bh<=0)return;val im=img(path);if(!im.complete||im.naturalWidth<=0)return;val s=min(bw/im.naturalWidth,bh/im.naturalHeight);val dw=im.naturalWidth*s;val dh=im.naturalHeight*s;g.save();g.globalAlpha=alpha.coerceIn(0.0,1.0);g.asDynamic().drawImage(im,x+(bw-dw)/2,y+(bh-dh)/2,dw,dh);g.restore()}
private fun drawCover(path:String,x:Double,y:Double,bw:Double,bh:Double,alpha:Double=1.0){if(bw<=0||bh<=0)return;val im=img(path);if(!im.complete||im.naturalWidth<=0)return;val s=max(bw/im.naturalWidth,bh/im.naturalHeight);val dw=im.naturalWidth*s;val dh=im.naturalHeight*s;g.save();g.beginPath();g.rect(x,y,bw,bh);g.clip();g.globalAlpha=alpha.coerceIn(0.0,1.0);g.asDynamic().drawImage(im,x+(bw-dw)/2,y+(bh-dh)/2,dw,dh);g.restore()}
private fun rect(x:Double,y:Double,bw:Double,bh:Double,color:String,alpha:Double=1.0,radius:Double=0.0,stroke:String?=null){g.save();g.globalAlpha=alpha;g.fillStyle=color;g.beginPath();if(radius>0)g.asDynamic().roundRect(x,y,bw,bh,radius)else g.rect(x,y,bw,bh);g.fill();if(stroke!=null){g.strokeStyle=stroke;g.lineWidth=max(1.0,m*0.002);g.stroke()};g.restore()}
private fun text(s:String,nx:Double,ny:Double,size:Double,color:String="#ffffff",align:String="left",maxWidth:Double?=null){g.save();g.fillStyle=color;g.font="700 "+max(9.0,m*size)+"px system-ui, sans-serif";g.asDynamic().textAlign=align;g.asDynamic().textBaseline="middle";if(maxWidth!=null)g.fillText(s,nx*w,ny*h,maxWidth)else g.fillText(s,nx*w,ny*h);g.restore()}
private fun button(s:String,l:Double,t:Double,r:Double,b:Double,accent:String=cyan(),enabled:Boolean=true){val x=l*w;val y=t*h;val bw=(r-l)*w;val bh=(b-t)*h;drawAsset("UI Elements/Button.png",x,y,bw,bh,if(enabled)0.97 else 0.35);rect(x+2,y+2,bw-4,bh-4,dark(),0.54,m*0.012,accent);text(s,(l+r)/2,(t+b)/2,min(0.026,(b-t)*0.34),if(enabled)"#ffffff"else muted(),"center",bw*0.94)}
private fun burst(x:Double,y:Double,color:String,count:Int=14){repeat(count.coerceAtMost(40)){i->val a=i.toDouble()/max(1,count)*PI*2+animationTime;val sp=m*(0.055+(i%5)*0.015);particles.add(Particle(x,y,cos(a)*sp,sin(a)*sp,0.42+(i%4)*0.075,color,m*(0.002+(i%3)*0.0012)))};impactX=x;impactY=y;impactTime=0.32}
private fun say(s:String,d:Double=2.0){messageText=s;messageTime=d}
private fun sfx(path:String){if(!sound)return;try{var a=audio[path];if(a==null){a=js("new Audio()");a.src="assets/SoundTrack/"+path;a.volume=0.42;audio[path]=a};a.currentTime=0;a.play()}catch(_:Throwable){}}
private fun setMusic(){if(!sound){try{music?.pause()}catch(_:Throwable){};return};val target=when(screen){"menu","story","worlds","levels","settings","help","difficulty","shop","features","modes","customize","miniguns"->"Music & Ambience/Main Menu Theme.wav";"won","campaign_complete"->"Music & Ambience/Victory Theme.wav";"failed"->"Music & Ambience/Game Over Theme.wav";else->"Music & Ambience/Gameplay Background.wav"};if(target==musicPath)return;try{music?.pause()}catch(_:Throwable){};try{music=js("new Audio()");music.src="assets/SoundTrack/"+target;music.loop=true;music.volume=0.25;musicPath=target;music.play()}catch(_:Throwable){}}
private fun currentStage()=stages.firstOrNull{it.id==levelId}?:Stage(levelId,worlds[worldOf(levelId)]+" "+((levelId-1)%10+1),8,emptyList())
private fun targetCount(id:Int)=when(mode){"boss_rush"->3;"editor_test"->intPref("editor_target_count",6).coerceIn(1,12);"procedural"->3+((id*13+intPref("procedural_seed",23))%10);else->(3+(id-1)/2).coerceAtMost(12)}
private fun guardHalf()=h*(when(difficulty){1->0.105;3->0.065;else->0.085})*(1.0+upgradeLevel("shield_mod").coerceAtMost(2)*0.14)*(if((effects["shield_expand"]?:0.0)>0)1.55 else 1.0)
private fun clampGuard(y:Double)=clamp(y,0.145+guardHalf()/h,0.935-guardHalf()/h)
private fun spawn(id:Int){
    enemies.clear();pickups.clear();particles.clear();trail.clear();hazardsCollected.clear();effects.clear()
    val count=targetCount(id).coerceIn(3,12)
    for(i in 0 until count){val col=i%4;val row=i/4;val yy=when(row){0->0.5;1->if(col%2==0)0.32 else 0.68;else->if(col%2==0)0.25 else 0.75};val x=0.49+col*0.115;val kind=if(mode=="boss_rush")3 else enemyKind(id,i);val configured=if(mode=="boss_rush")10+i*2 else if(id==TOTAL&&i==0)18 else enemyHealth(id,i);val hp=if(kind==0)3 else configured;enemies.add(Enemy(if(leftHanded)1-x else x,yy,true,kind,hp,1.2+(i%3)*0.6,true,0.0,1.2+(i%3)*0.16,if(kind==9)2 else 0,hp))}
    val types=listOf("shield_expand","slow_time","multi_catch","score_multiplier","extra_life","blade_speed","magnet","piercing");val n=if(mode=="procedural")2 else if(id%2==0&&mode!="editor_test")1 else 0
    repeat(n){i->pickups.add(Pickup(types[(id+i)%types.size],if(leftHanded)0.115 else 0.885,if(i%2==0)0.22 else 0.79))}
    guardY=0.5;bladeX=if(leftHanded)0.855 else 0.145;bladeY=guardY;vx=0.0;vy=0.0;bladeAngle=0.0;flying=false;slow=false;slowMeter=1.0;score=0;combo=0;bestCombo=0;comboWindow=0.0;elapsed=0.0;starsEarned=0;coinsEarned=0;switchActivated=false;keyCollected=false;teleportCooldown=0.0;extraLifeUsed=false;multiCatch=0;novaCooldown=0.0;novaFlash=0.0
    for((i,gun) in guns.withIndex()){gun.angle=0.0;gun.cooldown=0.35+i*0.25;gun.flash=0.0;gun.target=-1};messageText="";messageTime=0.0;lastFrame=0.0
}
private fun bladeScale()=1.0+upgradeLevel("overdrive").coerceAtMost(2)*0.12
private fun launch(){guardY=clampGuard(guardY);bladeX=if(leftHanded)0.855 else 0.145;bladeY=guardY;val speed=m*(0.50+difficulty*0.075+min(levelId,30)*0.003)*bladeScale();vx=if(leftHanded)-speed else speed;vy=speed*sin(levelId*1.37)*0.045;flying=true;trail.clear();burst(bladeX*w,bladeY*h,cyan(),8);sfx("Core Gameplay SFX/Blade Launch.wav")}
private fun startLevel(id:Int,force:Boolean=false){val safe=id.coerceIn(1,TOTAL);if(!force&&mode=="campaign"&&safe>unlocked){say("CLEAR PREVIOUS LEVELS TO UNLOCK THIS");return};levelId=safe;selectedWorld=worldOf(safe);spawn(safe);screen="playing";launch();persist()}
private fun fail(reason:String){if(screen!="playing")return;if(mode=="zen"||mode=="practice"){flying=false;vx=0.0;vy=0.0;bladeX=if(leftHanded)0.855 else 0.145;bladeY=guardY;say("PRACTICE RESET • NO RUN LOST");launch();return};if(!extraLifeUsed&&(effects["extra_life"]?:0.0)>0.0){extraLifeUsed=true;effects.remove("extra_life");enemies.filter{it.alive&&it.x<0.18}.forEach{it.x=0.78;it.y=guardY};flying=false;launch();say("EXTRA LIFE USED");return};flying=false;slow=false;vx=0.0;vy=0.0;screen="failed";say(reason,99999.0);put("total_fails",(intPref("total_fails",0)+1).toString());sfx(if(reason.contains("STUCK"))"Optional - Extra Sounds/Blade Stuck.wav"else"Core Gameplay SFX/Level Fail - Death.wav")}
private fun complete(){flying=false;vx=0.0;vy=0.0;val target=max(16.0,32.0-worldOf(levelId)*1.4-((levelId-1)%10)*0.25-(difficulty-1)*2.0);starsEarned=if(elapsed>target)1 else if(enemies.none{it.alive}||bestCombo>=3)3 else 2;coinsEarned=((80+levelId*8+starsEarned*30+min(bestCombo,12)*5)*(1.0+upgradeLevel("coin_magnet").coerceAtMost(2)*0.25)).toInt();coins+=coinsEarned;put("stars_"+levelId,max(starCount(levelId),starsEarned).toString());put("score_"+levelId,max(scoreBest(levelId),score).toString());unlocked=max(unlocked,min(levelId+1,TOTAL));put("total_clears",(intPref("total_clears",0)+1).toString());if(levelId%10==0&&levelId<TOTAL){val reward=(levelId/10).coerceIn(1,9);if(!gunUnlocked(reward))put("player_minigun_unlocked_"+reward,"true")};persist();screen=if(levelId>=TOTAL&&mode=="campaign")"campaign_complete"else"won";sfx("Core Gameplay SFX/Level Complete.wav")}
private fun registerHit(points:Int,x:Double,y:Double,color:String){combo=if(comboWindow>0.0)combo+1 else 1;comboWindow=2.25;bestCombo=max(bestCombo,combo);val mult=(if((effects["score_multiplier"]?:0.0)>0)2 else 1)*(if(combo>=5)2 else 1);score+=points*combo*mult;burst(x,y,color,if(combo>=3)20 else 13);if(combo>=2){say("COMBO x"+combo);sfx("UI & Feedback SFX/Combo - Streak.wav")}}
private fun enemyCenter(e:Enemy,i:Int):Pair<Double,Double>{val dx=when(e.kind){0->sin(animationTime*1.7+i*1.2)*0.014;2->sin(animationTime*1.25+i*1.4)*if(e.canSplit)0.035 else 0.02;3->sin(animationTime*0.75+i)*0.009;else->0.0};val dy=when(e.kind){0->cos(animationTime*1.3+i)*0.012;2->cos(animationTime*1.8+i)*0.02;else->0.0};val jump=if(e.kind==2&&e.jumpTime>0)-sin((1.0-e.jumpTime/0.58).coerceIn(0.0,1.0)*PI)*0.075 else 0.0;return Pair(clamp(e.x+dx,0.1,0.9),clamp(e.y+dy+jump,0.17,0.84))}
private fun updateEnemies(dt:Double){if(dt<=0)return;val breach=if(leftHanded)0.892 else 0.108;val dir=if(leftHanded)1.0 else -1.0;val target=clamp(guardY,0.18,0.82);val adaptive=if(dynamicDifficulty)1.0+min(intPref("total_clears",0),60)*0.0025 else 1.0;val dscale=(1.0+(difficulty-1)*0.18)*adaptive
    for((i,e) in enemies.withIndex()){if(!e.alive)continue
        when(e.kind){
            0->{val sp=(0.022+min(levelId,20)*0.00045)*dscale;e.x+=dir*sp*dt;e.y+=clamp(target-e.y,-sp*0.78*dt,sp*0.78*dt)}
            2->{if(e.jumpTime<=0){e.jumpCooldown-=dt;if(e.jumpCooldown<=0){e.jumpTime=0.58;e.jumpCooldown=1.20+(i%3)*0.16}};if(e.jumpTime>0){val sp=(0.19+min(levelId,40)*0.001)*dscale;e.x+=dir*sp*dt;e.y+=clamp(target-e.y,-sp*0.72*dt,sp*0.72*dt);e.jumpTime=max(0.0,e.jumpTime-dt)}}
            1,3,7,8,9->{val sp=when(e.kind){1->0.014;7->0.008;8->0.0075;9->0.012;else->0.011};e.x+=dir*sp*dscale*dt;val vy0=sp*(if(e.kind==7)1.2 else 0.52)*dt;if(e.kind==7)e.y+=sin(animationTime*1.6+i)*0.012*dt else e.y+=clamp(target-e.y,-vy0,vy0)}
            4->{e.x+=dir*0.009*dscale*dt;e.y+=clamp(target-e.y,-0.01*dt,0.01*dt);e.fireCooldown-=dt;if(e.fireCooldown<=0){val ally=enemies.filter{it.alive&&it!==e}.minByOrNull{dist2(it.x,it.y,e.x,e.y)};if(ally!=null&&dist2(ally.x,ally.y,e.x,e.y)<0.18*0.18){ally.hp=min(ally.hp+1,if(ally.kind==0)3 else 8);ally.maxHp=max(ally.maxHp,ally.hp);burst(ally.x*w,ally.y*h,"#5aff96",5)};e.fireCooldown=2.6}}
            5->{e.x+=dir*0.026*dscale*dt;e.y+=clamp(target-e.y,-0.025*dscale*dt,0.025*dscale*dt)}
            6->{e.fireCooldown-=dt;if(e.fireCooldown<=0&&((!leftHanded&&e.x<0.84)||(leftHanded&&e.x>0.16))){val off=((i*17+levelId*3)%31)/100.0;e.x=if(leftHanded)clamp(0.48-off,0.17,0.48)else clamp(0.52+off,0.52,0.83);e.y=clamp(0.22+((i*11+levelId)%56)/100.0,0.22,0.78);e.fireCooldown=2.1;burst(e.x*w,e.y*h,cyan(),8)};e.x+=dir*0.010*dscale*dt;e.y+=clamp(target-e.y,-0.009*dt,0.009*dt)}
        }
        if((!leftHanded&&e.x<=breach)||(leftHanded&&e.x>=breach)){e.x=breach;e.alive=false;burst(e.x*w,e.y*h,"#ff5c1c",30);val why=when(e.kind){0->"DRONE HIT THE WALL — YOU BURNED";2->"SLIME REACHED THE WALL — YOU BURNED";4->"HEALER REACHED THE WALL — YOU BURNED";5->"EXPLOSIVE BREACHED THE WALL — YOU BURNED";6->"TELEPORTER REACHED THE WALL — YOU BURNED";7->"SNIPER BREACHED THE WALL — YOU BURNED";else->"TURRET BREACHED THE WALL — YOU BURNED"};fail(why);return}
    }
}
private fun gunDamage(index:Int,x:Double,y:Double){val e=enemies.getOrNull(index)?:return;if(!e.alive)return;if(e.kind==9&&e.shieldHits>0){e.shieldHits--;burst(x,y,cyan(),5);sfx("Optional - Extra Sounds/Shield Break.wav");return};e.hp-=if(e.kind==0)droneDamage(e)else 1;burst(x,y,if(e.hp<=0)pink()else gold(),if(e.hp<=0)9 else 4);if(e.hp>0){score+=5;return};e.alive=false;registerHit(if(e.kind==3)90 else 45,x,y,cyan());if(e.kind==2&&e.canSplit){enemies.add(Enemy(clamp(e.x-0.03,0.12,0.90),clamp(e.y-0.025,0.18,0.82),true,2,1,8.0,false,maxHp=1));enemies.add(Enemy(clamp(e.x+0.03,0.12,0.90),clamp(e.y+0.025,0.18,0.82),true,2,1,8.0,false,maxHp=1));say("SLIME SPLIT")};if(e.kind==5){enemies.forEachIndexed{j,o->if(j!=index&&o.alive&&dist2(o.x,o.y,e.x,e.y)<0.13*0.13){o.hp-=1;if(o.hp<=0)o.alive=false}};burst(x,y,"#ff641c",18)};sfx("Core Gameplay SFX/Enemy Slice (Variation 1).wav")}
private fun updateGuns(dt:Double){val assigned=mutableSetOf<Int>();for((gi,gun) in guns.withIndex()){gun.flash=max(0.0,gun.flash-dt);val x=w*if(leftHanded)0.875 else 0.125;val y=h*if(gi==0)0.235 else 0.815;var free=-1;var freeD=Double.MAX_VALUE;var near=-1;var nearD=Double.MAX_VALUE
    for(i in enemies.indices){val e=enemies[i];if(!e.alive)continue;val c=enemyCenter(e,i);val d=dist2(x,y,c.first*w,c.second*h);if(d<nearD){nearD=d;near=i};if(i !in assigned&&d<freeD){freeD=d;free=i}}
    val idx=if(free>=0)free else near;if(idx<0||idx !in enemies.indices){gun.target=-1;continue};assigned.add(idx);gun.target=idx;val c=enemyCenter(enemies[idx],idx);gun.tx=c.first*w;gun.ty=c.second*h;val bearing=atan2(gun.ty-y,gun.tx-x)*180.0/PI;val desired=normAngle(bearing-180.0);gun.angle=normAngle(gun.angle+clamp(normAngle(desired-gun.angle),-300.0*dt,300.0*dt));val a=(180.0+gun.angle)*PI/180.0;gun.mx=x+cos(a)*m*0.075;gun.my=y+sin(a)*m*0.075;gun.cooldown=max(0.0,gun.cooldown-dt);if(gun.cooldown<=0&&abs(normAngle(bearing-180.0-gun.angle))<=17&&enemies[idx].alive){gun.cooldown=5.0;gun.flash=0.12;gunDamage(idx,gun.tx,gun.ty)}}}
private fun simulateStep(dt:Double){
    if(!flying||screen!="playing")return;val radius=m*0.022;val world=worldOf(levelId)
    when(world){2->vy+=sin(animationTime*1.35+levelId*0.17)*m*0.018*dt;3->vy+=cos(animationTime*1.1+levelId)*m*0.032*dt;7->{vx*=(1.0-0.06*dt).coerceAtLeast(0.90);vy*=(1.0-0.045*dt).coerceAtLeast(0.92)};8->vy+=sin(animationTime*2.2+levelId*0.3)*m*0.035*dt;9->vy*=(1.0-0.025*dt).coerceAtLeast(0.95)}
    if(world==6&&bladeY*h+vy*dt>h*0.86&&sin(animationTime*1.2)>0.78){fail("LAVA SURGE — STAY ABOVE THE HOT ZONE");return}
    val top=h*0.145+radius;val bottom=h*0.935-radius;val left=w*0.045+radius;val right=w*0.955-radius;var px=bladeX*w+vx*dt;var py=bladeY*h+vy*dt;val damp=exp(-0.004*dt*60);vx*=damp;vy*=damp;bladeAngle=(bladeAngle+1080*dt)%360
    if(py<top){py=top+(top-py);vy=abs(vy)*0.96;burst(px,py,cyan(),7);sfx("Core Gameplay SFX/Wall Ricochet (Variation 1).wav")}else if(py>bottom){py=bottom-(py-bottom);vy=-abs(vy)*0.96;burst(px,py,cyan(),7);sfx("Core Gameplay SFX/Wall Ricochet (Variation 2).wav")}
    if(!leftHanded&&px>right){px=right-(px-right);vx=-abs(vx)*0.96;burst(px,py,cyan(),7);sfx("Core Gameplay SFX/Wall Ricochet (Variation 3).wav")}else if(leftHanded&&px<left){px=left+(left-px);vx=abs(vx)*0.96;burst(px,py,cyan(),7);sfx("Core Gameplay SFX/Wall Ricochet (Variation 1).wav")}
    for((i,z) in currentStage().hazards.withIndex()){if(i in hazardsCollected)continue;val hx=z.x*w;val hy=z.y*h+if(z.type=="moving_hazard"||z.type=="moving_spikes")sin(animationTime*1.4+i)*h*0.09 else 0.0;val hw=max(z.width*w*0.5,radius);val hh=max(z.height*h*0.5,radius);val hit=px+radius>=hx-hw&&px-radius<=hx+hw&&py+radius>=hy-hh&&py-radius<=hy+hh;if(!hit)continue
        when(z.type){"moving_hazard"->{if(world==1){vy=if(py<=hy)-abs(vy).coerceAtLeast(m*0.16)else abs(vy).coerceAtLeast(m*0.16);vx*=0.96;burst(px,py,gold(),12);say("CIRCUIT RAIL DEFLECTED")}else{fail("MOVING HAZARD HIT");return}}
            "teleporter"->{if(teleportCooldown<=0){val dest=currentStage().hazards.withIndex().firstOrNull{it.index!=i&&it.value.type=="teleporter"};if(dest!=null){px=dest.value.x*w;py=dest.value.y*h;teleportCooldown=0.85;burst(px,py,cyan(),12);say("PORTAL WARP");sfx("Optional - Extra Sounds/Teleport - Warp.wav")}}}
            "power_up"->{hazardsCollected.add(i);score+=250;effects["score_multiplier"]=8.0;burst(hx,hy,gold(),16);say("POWER-UP • +2 RETURNS");sfx("Optional - Extra Sounds/Power-Up Collect.wav")}
            "switch"->{hazardsCollected.add(i);switchActivated=true;burst(hx,hy,gold(),12);sfx("Core Gameplay SFX/Switch Activation.wav");say("SWITCH ACTIVATED")}
            "key"->{hazardsCollected.add(i);keyCollected=true;burst(hx,hy,gold(),12);say("KEY COLLECTED")}
            "door"->{if(keyCollected){hazardsCollected.add(i);burst(hx,hy,cyan(),14);say("DOOR UNLOCKED")}else{vx=-vx*0.82;vy=-vy*0.82;say("DOOR LOCKED • FIND THE KEY")}}
            "breakable_wall"->{hazardsCollected.add(i);burst(hx,hy,gold(),18);sfx("Core Gameplay SFX/Crate Break.wav");say("WALL BROKEN")}
            "gravity_well"->{val dx=hx-px;val dy=hy-py;val d=hypot(dx,dy).coerceAtLeast(1.0);vx+=dx/d*m*0.20*dt;vy+=dy/d*m*0.20*dt}
            "conveyor_belt"->vx+=(if(px<hx)-1 else 1)*m*0.05*dt
            "laser","rotating_laser"->{fail("LASER HIT");return}
            "sticky_wall"->{fail("STICKY WALL — BLADE STUCK");return}
            else->{fail(if(z.type.contains("spike"))"SPIKES HIT"else"HAZARD HIT");return}
        }
    }
    val contact=if(leftHanded)w*0.902-radius else w*0.098+radius
    if((!leftHanded&&px<contact)||(leftHanded&&px>contact)){val half=guardHalf();val center=guardY*h;val caught=abs(py-center)<=half+radius;val auto=!caught&&multiCatch>0
        if(caught||auto){if(auto){multiCatch--;say("MULTI-CATCH SAVE • "+multiCatch+" LEFT")};px=contact;val catchCenter=if(auto)py else center;val offset=clamp((py-catchCenter)/(half+radius),-1.0,1.0);val speed=clamp(hypot(vx,vy)*1.035,m*0.46*bladeScale(),m*0.90*bladeScale());val a=offset*1.10;vx=(if(leftHanded)-1 else 1)*abs(cos(a)*speed).coerceAtLeast(m*0.32);vy=sin(a)*speed;combo=min(99,combo+1);bestCombo=max(bestCombo,combo);comboWindow=2.0;burst(px,py,gold(),12);say("WALL SAVE");if(abs(offset)<=0.16){val bonus=150*max(combo,1);score+=bonus;say("PERFECT CATCH + "+bonus);burst(px,py,gold(),18)};sfx("Core Gameplay SFX/Wall Ricochet (Variation 1).wav")}
        else{bladeX=px/w;bladeY=py/h;fail(if(leftHanded)"THE BLADE PASSED THE RIGHT WALL"else"THE BLADE PASSED THE LEFT WALL");return}}
    for((i,e) in enemies.withIndex()){if(!e.alive||e.hitCooldown>0)continue;val c=enemyCenter(e,i);val ex=c.first*w;val ey=c.second*h;val hitR=radius+m*(if(e.kind==3)0.055 else 0.035);if(dist2(px,py,ex,ey)>hitR*hitR)continue
        if(e.kind==9&&e.shieldHits>0){e.shieldHits--;burst(ex,ey,cyan(),14);say("ENERGY SHIELD HIT • "+e.shieldHits+" CHARGES");sfx("Optional - Extra Sounds/Shield Break.wav")}
        e.hp-=if(e.kind==0)droneDamage(e)else if((effects["piercing"]?:0.0)>0)2 else 1;e.hitCooldown=0.32
        if(e.hp<=0){e.alive=false;registerHit(if(e.kind==3)500 else if(e.kind==5)300 else 100,ex,ey,pink());if(e.kind==2&&e.canSplit){enemies.add(Enemy(clamp(e.x-0.03,0.12,0.90),clamp(e.y-0.035,0.18,0.82),true,2,1,8.0,false,maxHp=1));enemies.add(Enemy(clamp(e.x+0.03,0.12,0.90),clamp(e.y+0.035,0.18,0.82),true,2,1,8.0,false,maxHp=1));say("SLIME SPLIT")};if(e.kind==5)enemies.forEachIndexed{j,o->if(j!=i&&o.alive&&dist2(o.x,o.y,e.x,e.y)<0.13*0.13){o.hp-=2;if(o.hp<=0)o.alive=false}};sfx("Core Gameplay SFX/Enemy Slice (Variation 1).wav")}
        else{score+=50;burst(ex,ey,gold(),12);say("ENEMY HIT");sfx("Optional - Extra Sounds/Shield Break.wav")}
        val speed=hypot(vx,vy).coerceAtLeast(1.0);val newSpeed=clamp(speed,m*0.46*bladeScale(),m*0.90*bladeScale());vx*=newSpeed/speed;vy*=newSpeed/speed;val d=hypot(vx,vy).coerceAtLeast(1.0);val pass=hitR+m*0.008;px=ex+vx/d*pass;py=ey+vy/d*pass;burst(ex,ey,pink(),14);break
    }
    for(p in pickups){if(!p.active)continue;val x=p.x*w;val y=p.y*h;val r=radius+m*0.026;if(dist2(px,py,x,y)>r*r)continue;p.active=false
        when(p.type){"shield_expand"->effects["shield_expand"]=12.0;"slow_time"->{effects["slow_time"]=8.0;vx*=0.72;vy*=0.72};"score_multiplier"->effects["score_multiplier"]=12.0;"multi_catch"->multiCatch=min(6,multiCatch+2);"piercing"->effects["piercing"]=8.0;"extra_life"->{effects["extra_life"]=30.0;extraLifeUsed=false};"blade_speed"->{effects["blade_speed"]=10.0;vx*=1.2;vy*=1.2};"magnet"->{score+=200;coins+=25;persist()}}
        burst(x,y,gold(),18);say("POWER-UP: "+p.type.replace('_',' ').uppercase());sfx("Optional - Extra Sounds/Power-Up Collect.wav")}
    bladeX=clamp(px/w,0.0,1.0);bladeY=clamp(py/h,0.0,1.0);trail.add(Pair(px,py));while(trail.size>24)trail.removeAt(0);if(enemies.none{it.alive})complete()
}
private fun nova(){
    if(upgradeLevel("nova")==0){openShop("playing");return};if(novaCooldown>0){say("NOVA RECHARGING: "+ceil(novaCooldown).toInt()+"s");return}
    val core=upgradeLevel("pulse_core").coerceAtMost(2);val x=bladeX*w;val y=bladeY*h;val radius=m*(0.18+core*0.045);var hits=0;val spawned=mutableListOf<Enemy>()
    enemies.forEachIndexed{i,e->if(!e.alive)return@forEachIndexed;val c=enemyCenter(e,i);val ex=c.first*w;val ey=c.second*h;if(dist2(x,y,ex,ey)>radius*radius)return@forEachIndexed;hits++;e.hp--;burst(ex,ey,if(e.hp<=0)cyan()else gold(),12);if(e.hp<=0){e.alive=false;registerHit(if(e.kind==3)250 else 100,ex,ey,cyan());if(e.kind==2&&e.canSplit){spawned.add(Enemy(clamp(e.x-0.035,0.11,0.90),clamp(e.y-0.025,0.2,0.82),true,2,1,8.0,false,maxHp=1));spawned.add(Enemy(clamp(e.x+0.035,0.11,0.90),clamp(e.y+0.025,0.2,0.82),true,2,1,8.0,false,maxHp=1))}}else score+=35}
    if(hits==0){say("NO ENEMIES IN NOVA RANGE");return};enemies.addAll(spawned);novaCooldown=max(3.0,8.0-core*1.75);novaFlash=0.42;novaX=x;novaY=y;novaRadius=radius;burst(x,y,cyan(),34);say("NOVA PULSE! "+hits+" ENEMY HIT");sfx("Optional - Extra Sounds/Shield Break.wav")
}
private fun openShop(back:String){shopReturn=back;screen="shop";slow=false}
private fun buy(i:Int){val item=upgrades.getOrNull(i)?:return;val lvl=upgradeLevel(item.id).coerceAtMost(item.max);if(item.id=="pulse_core"&&upgradeLevel("nova")==0){say("UNLOCK NOVA PULSE FIRST");return};if(lvl>=item.max){say("UPGRADE ALREADY MAXED");return};val price=cost(item);if(coins<price){say("NEED "+(price-coins)+" MORE COINS");return};coins-=price;put("upgrade_"+item.id,(lvl+1).toString());persist();say(item.title+" UPGRADED!");burst(w*0.5,h*0.48,cyan(),22);sfx("Optional - Extra Sounds/Power-Up Collect.wav")}
private fun selectMode(s:String){mode=s;put("game_mode",s);startLevel(if(s=="campaign")unlocked else 1,true)}
