        "story"->when{inside(x,y,0.08,0.815,0.32,0.90)->screen="menu";storyPage>0&&inside(x,y,0.36,0.815,0.62,0.90)->storyPage--;storyPage<2&&inside(x,y,0.66,0.815,0.92,0.90)->storyPage++}
