        "modes"->{val names=listOf("campaign","endless","time_attack","zen","boss_rush","speedrun","procedural","local_coop");val i=names.indices.firstOrNull{inside(x,y,0.10,0.245+it*0.067,0.90,0.312+it*0.067)};if(i!=null)selectMode(names[i])else if(inside(x,y,0.24,0.80,0.76,0.88))screen="features"}
