        "miniguns"->{var hit=false;for(i in 0 until 10){val col=i%5;val row=i/5;val l=0.035+col*0.188;val t=0.25+row*0.255;if(inside(x,y,l,t,l+0.175,t+0.22)){if(gunUnlocked(i)){selectedGun=i;put("player_minigun",i.toString());say("EQUIPPED: "+worlds[i].uppercase())}else say("CLEAR LEVEL "+(i*10)+" TO UNLOCK");hit=true;break}};if(!hit&&inside(x,y,0.36,0.835,0.64,0.925))screen="customize"}
