private fun worldArt(i:Int)=when(i){0->"World Art/Neon Grid.png";1->"World Art/Crimson Circuit.png";2->"World Art/Azure Vault.png";3->"World Art/Magenta Maze.png";4->"World Art/Golden Core.png";else->"Backgrounds & Environments/Menu Background.png"}
private fun background(menu:Boolean=false){g.fillStyle=dark();g.fillRect(0.0,0.0,w,h);if(menu)drawCover(if(screen=="menu")"UI Elements/Main Menu Background.png"else"Backgrounds & Environments/Menu Background.png",0.0,0.0,w,h,0.96)else drawCover("Backgrounds & Environments/Gameplay Background.png",w*0.035,h*0.135,w*0.93,h*0.805,0.92);g.save();g.globalAlpha=0.5;g.strokeStyle=grid();g.lineWidth=max(1.0,m*0.0012);for(i in 1..5){val x=w*i/6.0;g.beginPath();g.moveTo(x,h*0.02);g.lineTo(x,h*0.98);g.stroke()};for(i in 1..12){val y=h*i/13.0;g.beginPath();g.moveTo(w*0.02,y);g.lineTo(w*0.98,y);g.stroke()};g.restore()}
private fun drawMenu(){background(true);drawAsset("App Icon & Logo/Game Logo.png",w*0.16,h*0.105,w*0.68,h*0.19);text("BOUNCE OFF ENEMIES  •  GUARD THE LEFT WALL",0.5,0.315,0.018,muted(),"center");text("◈ "+coins,0.91,0.105,0.026,gold(),"right");rect(w*0.285,h*0.315,w*0.43,h*0.58,dark(),0.76,m*0.03,cyan());button("PLAY CAMPAIGN",0.305,0.340,0.695,0.415,gold());button("LEVEL SELECT",0.305,0.430,0.695,0.505,cyan());button("MORE FEATURES",0.305,0.520,0.695,0.595,pink());button("BLADE SHOP",0.305,0.610,0.695,0.685,gold());button("SETTINGS",0.305,0.700,0.695,0.775,cyan());button("THE STORY",0.355,0.805,0.645,0.880,pink());val total=(1..TOTAL).sumOf{starCount(it)};text("LEVEL "+unlocked+"/"+TOTAL+"     ★ "+total+"/"+(TOTAL*3),0.5,0.925,0.019,muted(),"center");text("COLLECT COINS  •  UPGRADE YOUR BLADE  •  SURVIVE EVERY WAVE",0.5,0.970,0.014,muted(),"center")}
private fun drawDifficulty(){background(true);text("CHOOSE YOUR DIFFICULTY",0.5,0.18,0.05,"#ffffff","center");text("Easy gives a wider shield. Hard makes the blade faster.",0.5,0.245,0.019,muted(),"center");for(i in 1..3){val l=0.12+(i-1)*0.265;button(listOf("★☆☆ EASY","★★☆ NORMAL","★★★ HARD")[i-1],l,0.34,l+0.23,0.48,if(difficulty==i)gold()else cyan())};button("START CAMPAIGN  •  LEVEL "+unlocked,0.24,0.59,0.76,0.69,gold());button("BACK",0.30,0.73,0.70,0.82,cyan());text("Progress is saved in this browser.",0.5,0.91,0.017,muted(),"center")}
private fun drawWorlds(){background(true);text("CHOOSE YOUR WORLD",0.5,0.105,0.052,"#ffffff","center");text("100 LEVELS  •  10 WORLDS  •  LOCAL CAMPAIGN",0.5,0.17,0.018,muted(),"center");for(i in 0 until 10){val row=i%5;val col=i/5;val l=if(col==0)0.045 else 0.515;val t=0.225+row*0.126;val avail=unlocked>=i*10+1;val cnt=(i*10+1..i*10+10).sumOf{starCount(it)};drawCover(worldArt(i),l*w,t*h,0.44*w,0.105*h,if(avail)0.78 else 0.25);rect(l*w,t*h,0.44*w,0.105*h,"#030612",if(avail)0.62 else 0.84,m*0.018,if(avail)cyan()else muted());text((i+1).toString().padStart(2,'0')+"  "+worlds[i],l+0.22,t+0.041,0.022,if(avail)"#ffffff"else muted(),"center");text(if(avail)"$cnt/30 ★"else"LOCKED",l+0.22,t+0.078,0.015,if(avail)gold()else muted(),"center")};button("BACK",0.20,0.875,0.80,0.955,gold())}
private fun drawLevels(){background(true);text(worlds[selectedWorld].uppercase(),0.5,0.105,0.055,"#ffffff","center");text("LEVELS "+(selectedWorld*10+1)+"-"+(selectedWorld*10+10)+"  •  UNLOCKED "+unlocked+"/"+TOTAL,0.5,0.155,0.018,cyan(),"center");for(i in 1..3){val l=0.035+(i-1)*0.315;button(listOf("★☆☆ EASY","★★☆ NORMAL","★★★ HARD")[i-1],l,0.185,l+0.30,0.26,if(difficulty==i)gold()else cyan())};for(local in 1..10){val id=selectedWorld*10+local;val col=(local-1)%4;val row=(local-1)/4;val l=0.035+col*0.24;val t=0.29+row*0.135;val active=id<=unlocked;val stars=starCount(id);button(local.toString().padStart(2,'0')+"  "+"★".repeat(stars)+"☆".repeat(3-stars),l,t,l+0.23,t+0.095,if(active)cyan()else muted(),active);text(stages.firstOrNull{it.id==id}?.name?:worlds[selectedWorld],l+0.115,t+0.077,0.009,if(active)"#d9e5f7"else muted(),"center",0.215*w)};text("STAR RATING USES COMPLETION TIME AND COMBOS",0.5,0.735,0.014,muted(),"center");button("BACK TO WORLDS",0.20,0.83,0.80,0.915,gold())}
private fun drawEnemy(e:Enemy,i:Int){val c=enemyCenter(e,i);val x=c.first*w;val y=c.second*h;val radius=m*when(e.kind){1,7->0.033;2->if(e.canSplit)0.031 else 0.020;3->0.052;5->0.038;6->0.034;8->0.040;else->0.030};val path=when(e.kind){1,3,7,8,9->"Gameplay Sprites/Enemy Turret.png";2->"Gameplay Sprites/Enemy Slime.png";6->"Gameplay Sprites/Portal.png";else->"Gameplay Sprites/Enemy Drone.png"};val size=radius*when(e.kind){3->3.2;5->2.7;6->2.8;8->2.6;else->2.35};g.save();g.globalAlpha=if(e.hitCooldown>0)0.72 else 1.0;g.strokeStyle=if(e.hp<=max(1,e.maxHp/3))pink()else if(e.kind==1||e.kind==3||e.kind==7||e.kind==8||e.kind==9)gold()else cyan();g.lineWidth=max(1.2,m*0.002);g.beginPath();g.arc(x,y,size*0.74,0.0,PI*2);g.stroke();if(!reducedMotion){g.globalAlpha=0.28+abs(sin(animationTime*4+i))*0.45;g.beginPath();g.arc(x,y,size*(0.9+abs(sin(animationTime*2.2+i))*0.1),0.0,PI*2);g.stroke()};g.globalAlpha=1.0;if(e.kind==9&&e.shieldHits>0){g.strokeStyle=cyan();g.lineWidth=m*0.004;g.beginPath();g.arc(x,y,size*0.92,0.0,PI*2);g.stroke()};drawAsset(path,x-size,y-size,size*2,size*2);val bw=size*1.7;val bh=max(3.0,m*0.006);rect(x-bw/2,y-size-bh*2,bw,bh,"#29354a",1.0,bh/2);rect(x-bw/2,y-size-bh*2,bw*clamp(e.hp.toDouble()/max(1,e.maxHp),0.0,1.0),bh,if(e.hp<=max(1,e.maxHp/3))pink()else"#5cffbd",1.0,bh/2);if(e.kind==9&&e.shieldHits>0)text("SHIELD "+e.shieldHits,x/w,(y-size*1.5)/h,0.012,cyan(),"center");g.restore()}
private fun drawGuns(){for((i,gun) in guns.withIndex()){val x=w*if(leftHanded)0.875 else 0.125;val y=h*if(i==0)0.235 else 0.815;if(gun.flash>0&&gun.target>=0){g.save();g.globalAlpha=clamp(gun.flash/0.12,0.0,1.0)*0.86;g.strokeStyle="#3ae9ff";g.lineWidth=max(1.5,m*0.003);g.beginPath();g.moveTo(gun.mx,gun.my);g.lineTo(gun.tx,gun.ty);g.stroke();g.fillStyle="#ffd66e";g.beginPath();g.arc(gun.tx,gun.ty,max(2.0,m*0.003),0.0,PI*2);g.fill();g.restore()};g.save();g.translate(x,y);g.rotate(gun.angle*PI/180.0);drawAsset("Player Miniguns/Gameplay/Minigun_"+gunKeys[gunIndex()]+".png",-m*0.095,-m*0.0575,m*0.19,m*0.115);g.restore()}}
private fun drawHazards(){for((i,z) in currentStage().hazards.withIndex()){if(i in hazardsCollected)continue;val x=z.x*w;val y=z.y*h+if(z.type=="moving_hazard"||z.type=="moving_spikes")sin(animationTime*1.4+i)*h*0.09 else 0.0;val bw=max(m*0.025,z.width*w);val bh=max(m*0.014,z.height*h);when(z.type){"teleporter"->drawAsset("Gameplay Sprites/Portal.png",x-bw*0.5,y-bh*1.6,bw,bh*3.2);"power_up","key","switch"->{g.save();g.shadowColor=gold();g.shadowBlur=m*0.025;g.fillStyle=gold();g.beginPath();g.arc(x,y,m*0.018,0.0,PI*2);g.fill();g.restore();text(if(z.type=="key")"K"else if(z.type=="switch")"S"else"+",x/w,y/h,0.02,dark(),"center")};"laser","rotating_laser"->{g.save();g.strokeStyle=pink();g.lineWidth=max(2.0,m*0.006);g.shadowColor=pink();g.shadowBlur=m*0.02;g.beginPath();if(z.type=="rotating_laser"){val a=animationTime*1.35+i*0.4;g.moveTo(x-cos(a)*bw/2,y-sin(a)*bw/2);g.lineTo(x+cos(a)*bw/2,y+sin(a)*bw/2)}else{g.moveTo(x-bw/2,y);g.lineTo(x+bw/2,y)};g.stroke();g.restore()};"spikes","moving_spikes"->{g.fillStyle=pink();val n=max(3,(bw/(m*0.05)).toInt());for(p in 0 until n){val sw=bw/n;g.beginPath();g.moveTo(x-bw/2+p*sw,y+bh/2);g.lineTo(x-bw/2+p*sw+sw/2,y-bh);g.lineTo(x-bw/2+(p+1)*sw,y+bh/2);g.closePath();g.fill()}};else->rect(x-bw/2,y-bh/2,bw,bh,if(z.type.contains("wall"))gold()else pink(),0.55,m*0.004)}}}
private fun drawEnvironment(){when(worldOf(levelId)){5->{g.strokeStyle="#b169ff";g.globalAlpha=0.28;for(i in 0..5){val x=w*(0.12+i*0.15);g.beginPath();g.arc(x,h*(0.3+(i%3)*0.22),m*(0.018+abs(sin(animationTime*0.7+i))*0.03),0.0,PI*2);g.stroke()};g.globalAlpha=1.0};6->{rect(w*0.035,h*0.82,w*0.93,h*0.12,"#fa500c",0.12);g.strokeStyle="#ff9b32";g.globalAlpha=0.45;for(i in 0..8){val x=w*(0.08+i*0.105);val sw=sin(animationTime*1.1+i*0.8)*m*0.018;g.beginPath();g.moveTo(x,h*0.90);g.lineTo(x+sw,h*(0.72-(i%3)*0.04));g.stroke()};g.globalAlpha=1.0};7->{g.strokeStyle="#46b4ff";g.globalAlpha=0.35;for(i in 0..2){val x=w*(0.32+i*0.28);val y=h*(0.33+(i%2)*0.34);val r=m*(0.018+((animationTime*0.05+i*0.02)%0.045));g.beginPath();g.arc(x,y,r,0.0,PI*2);g.stroke();g.beginPath();g.arc(x,y,r*1.6,0.0,PI*2);g.stroke()};g.globalAlpha=1.0};8->{g.strokeStyle="#aad2ff";g.globalAlpha=0.45;for(i in 0..17){val x=w*(((i*53+17)%997)/997.0);val p=(animationTime*(0.35+(i%4)*0.06)+i*0.071)%1.0;val y=h*(0.14+p*0.77);g.beginPath();g.moveTo(x,y);g.lineTo(x-m*0.018,y+m*0.025);g.stroke()};g.globalAlpha=1.0};9->{for(i in 0..13){val x=w*(((i*73+11)%991)/991.0);val y=h*(0.16+((i*43+7)%771)/1000.0);g.fillStyle=gold();g.globalAlpha=0.18+abs(sin(animationTime*2+i))*0.28;g.beginPath();g.arc(x,y,max(1.2,m*0.002),0.0,PI*2);g.fill()};g.globalAlpha=1.0}}}
private fun drawEffects(){particles.forEach{p->g.save();g.globalAlpha=clamp(p.life/0.65,0.0,1.0);g.fillStyle=p.color;g.shadowColor=p.color;g.shadowBlur=p.radius*4;g.beginPath();g.arc(p.x,p.y,max(1.0,p.radius),0.0,PI*2);g.fill();g.restore()};if(impactTime>0){val a=clamp(impactTime/0.32,0.0,1.0);g.save();g.globalAlpha=a*0.72;g.strokeStyle=gold();g.lineWidth=m*0.003;for(i in 0..2){g.beginPath();g.arc(impactX,impactY,m*(0.025+i*0.018+(1-a)*0.02),0.0,PI*2);g.stroke()};g.restore()}}
private fun drawBlade(){val x=bladeX*w;val y=bladeY*h;trail.forEachIndexed{i,p->g.save();g.globalAlpha=i.toDouble()/max(1,trail.size)*0.22;g.fillStyle=cyan();g.beginPath();g.arc(p.first,p.second,m*0.013,0.0,PI*2);g.fill();g.restore()};g.save();if(flying){g.strokeStyle=cyan();g.lineWidth=max(2.0,m*0.003);g.shadowColor=cyan();g.shadowBlur=m*0.035;g.beginPath();g.arc(x,y,m*0.048,0.0,PI*2);g.stroke()};g.translate(x,y);g.rotate(bladeAngle*PI/180.0);drawAsset(if(flying)"Gameplay Sprites/Blade.png"else"Gameplay Sprites/Blade Idle.png",-m*0.039,-m*0.039,m*0.078,m*0.078);val skin=intPref("blade_skin",0);if(skin>0){g.strokeStyle=palettes[skin%6][0];g.lineWidth=m*0.003;g.beginPath();g.arc(0.0,0.0,m*0.044,0.0,PI*2);g.stroke()};g.restore()}
private fun drawGame(){background(false);drawAsset("UI Elements/UI Panel.png",w*0.025,h*0.012,w*0.95,h*0.113,0.9);drawEnvironment();val arenaL=w*0.035;val arenaT=h*0.135;val arenaW=w*0.93;val arenaH=h*0.805;rect(arenaL,arenaT,arenaW,arenaH,"#050a18",0.08,m*0.018,cyan());val wall=w*if(leftHanded)0.955 else 0.045;val pulse=if(reducedMotion)0.65 else 0.35+0.65*abs(sin(animationTime*4));g.save();g.strokeStyle=cyan();g.lineWidth=m*(0.003+pulse*0.003);g.shadowColor=cyan();g.shadowBlur=m*(0.01+pulse*0.015);g.globalAlpha=0.4+pulse*0.55;g.beginPath();g.moveTo(wall,arenaT+3);g.lineTo(wall,arenaT+arenaH-3);g.stroke();g.restore();for(i in 0..11){val p=(animationTime*0.45+i/12.0)%1.0;val y=arenaT+p*arenaH;g.save();g.strokeStyle="#ebffff";g.globalAlpha=0.15+pulse*0.28;g.beginPath();g.moveTo(wall-m*0.015,y);g.lineTo(wall+m*0.015,y);g.stroke();g.restore()};drawHazards();drawEffects();for((i,e) in enemies.withIndex())if(e.alive)drawEnemy(e,i);drawGuns();val half=guardHalf();val center=guardY*h;val left=if(leftHanded)w*0.902 else w*0.043;val right=if(leftHanded)w*0.957 else w*0.098;val shields=listOf(cyan(),"#6eff9c","#b482ff","#ff735a","#ffbd4a","#50c8ff");val shield=shields[intPref("shield_skin",0)%6];rect(left,center-half,right-left,half*2,shield,0.38,m*0.012,shield);rect((left+right)/2-m*0.002,center-half+m*0.012,m*0.004,half*2-m*0.024,"#ffffff",0.85,m*0.003);drawBlade();text("BOUNCE BLADE",0.07,0.047,0.025,"#ffffff");text("LEVEL "+levelId+"/"+TOTAL,0.49,0.047,0.022,cyan(),"center");val pl=if(leftHanded)0.03 else 0.825;val pr=if(leftHanded)0.175 else 0.97;button("Ⅱ",pl,0.027,pr,0.110,pink());text("SCORE "+score,0.07,0.092,0.019,gold());text("TARGETS "+enemies.count{it.alive},0.50,0.092,0.019,pink(),"center");text("SAVE STREAK "+combo,0.78,0.092,0.016,cyan(),"right");button(if(upgradeLevel("nova")>0)if(novaCooldown>0)"NOVA "+ceil(novaCooldown).toInt()+"s"else"NOVA"else"SHOP",0.82,0.83,0.97,0.94,if(upgradeLevel("nova")>0)cyan()else gold());rect(w*0.04,h*0.955,w*0.22,h*0.008,"#29354a",0.9,m*0.004);rect(w*0.04,h*0.955,w*0.22*slowMeter,h*0.008,"#bd7bff",0.95,m*0.004);text("HOLD A SECOND TOUCH TO SLOW TIME",0.5,0.975,0.012,muted(),"center");if(messageTime>0&&messageText.isNotBlank())text(messageText,0.5,0.855,0.019,gold(),"center",w*0.9);if(novaFlash>0){g.save();g.globalAlpha=novaFlash/0.42;g.strokeStyle=cyan();g.lineWidth=m*0.005;g.shadowColor=cyan();g.shadowBlur=m*0.03;g.beginPath();g.arc(novaX,novaY,novaRadius*(1.2-novaFlash),0.0,PI*2);g.stroke();g.beginPath();g.arc(novaX,novaY,novaRadius*0.72*(1.2-novaFlash),0.0,PI*2);g.stroke();g.restore()}}
