private fun drawStory(){background(true);drawCover(worldArt(if(storyPage==0)0 else if(storyPage==1)1 else 4),0.0,0.0,w,h,0.55);rect(w*0.045,h*0.205,w*0.91,h*0.58,"#030612",0.78,m*0.025);text("THE STORY",0.5,0.115,0.06,gold(),"center");text("CHAPTER "+(storyPage+1)+" / 3",0.5,0.18,0.02,cyan(),"center");val chapters=listOf(listOf("In the beginning, there was only the Lumen Grid — a shimmering tapestry","of light and data, woven from the dreams of a thousand forgotten stars.","At its heart burned the Golden Core, the first spark of all creation.","The Guardians were forged to protect the Grid and wield shields of pure intent."),listOf("From the edges of the void came the Corruption: static twisting the Grid","into ravenous enemies. The Guardians created the Bounce Blade, a shard of","the Core designed to ricochet through the Corruption and return to its master.","But the Corruption poisoned the Blade with wild, uncontrollable momentum."),listOf("You are the last Guardian. Your shield is the final wall between order","and oblivion. Across ten worlds, destroy the Corruption and catch the light.","Every enemy struck and every perfect catch strengthens the bond between you.","Catch the Blade. Save the light. Become the legend."))[storyPage];chapters.forEachIndexed{i,s->text(s,0.5,0.32+i*0.075,0.019,"#eef5ff","center",w*0.84)};button("BACK",0.08,0.815,0.32,0.90,gold());button("PREVIOUS",0.36,0.815,0.62,0.90,cyan(),storyPage>0);button("NEXT",0.66,0.815,0.92,0.90,pink(),storyPage<2)}
