private fun drawModes(){background(true);text("GAME MODES",0.5,0.14,0.052,"#ffffff","center");val names=listOf("campaign","endless","time_attack","zen","boss_rush","speedrun","procedural","local_coop");val labels=listOf("CAMPAIGN","ENDLESS","TIME ATTACK","ZEN / PRACTICE","BOSS RUSH","SPEEDRUN","PROCEDURAL ARENA","LOCAL CO-OP");names.forEachIndexed{i,n->val t=0.245+i*0.067;button(labels[i],0.10,t,0.90,t+0.061,if(mode==n)gold()else cyan())};button("BACK",0.24,0.80,0.76,0.88,gold())}
private fun drawCustomize(){background(true);text("CUSTOMIZATION",0.5,0.14,0.052,"#ffffff","center");button("COLOR THEME: "+listOf("CYAN","GREEN","VIOLET","CRIMSON","SOLAR","OCEAN")[theme],0.18,0.21,0.82,0.29,cyan());button("BLADE SKIN: "+(intPref("blade_skin",0)+1)+" / 6",0.18,0.33,0.82,0.41,gold());button("SHIELD SIDE: "+if(leftHanded)"RIGHT"else"LEFT",0.18,0.45,0.82,0.53,pink());button("MINIGUN ARMORY",0.18,0.57,0.82,0.65,cyan());button("BACK",0.24,0.80,0.76,0.88,gold())}
private fun drawMiniguns(){background(true);text("PLAYER MINIGUN ARMORY",0.5,0.13,0.047,"#ffffff","center");for(i in 0 until 10){val col=i%5;val row=i/5;val l=0.035+col*0.188;val t=0.25+row*0.255;val avail=gunUnlocked(i);drawAsset("Player Miniguns/Menu/Minigun_"+gunKeys[i]+".png",l*w,t*h,0.175*w,0.15*h,if(avail)1.0 else 0.26);rect(l*w,t*h,0.175*w,0.22*h,"#030612",if(avail)0.20 else 0.70,m*0.012,if(selectedGun==i)gold()else if(avail)cyan()else muted());text(worlds[i],l+0.0875,t+0.176,0.012,if(avail)"#ffffff"else muted(),"center",0.17*w);text(if(avail)if(selectedGun==i)"EQUIPPED"else"UNLOCKED"else"CLEAR LV "+(i*10),l+0.0875,t+0.205,0.010,if(avail)gold()else muted(),"center",0.17*w)};button("BACK",0.36,0.835,0.64,0.925,gold())}
private fun drawSettings(){background(true);text("SETTINGS",0.5,0.14,0.052,"#ffffff","center");button("SOUND: "+if(sound)"ON"else"OFF",0.18,0.24,0.82,0.32,cyan());button("REDUCED MOTION: "+if(reducedMotion)"ON"else"OFF",0.18,0.36,0.82,0.44,gold());button("DYNAMIC DIFFICULTY: "+if(dynamicDifficulty)"ON"else"OFF",0.18,0.48,0.82,0.56,pink());button("SHIELD SIDE: "+if(leftHanded)"RIGHT"else"LEFT",0.18,0.60,0.82,0.68,cyan());text("Saved in this browser's local storage.",0.5,0.74,0.016,muted(),"center");button("BACK",0.24,0.80,0.76,0.88,gold())}
private fun drawHelp(){background(true);text("HOW TO PLAY",0.5,0.14,0.052,"#ffffff","center");val lines=listOf("The blade launches automatically when each stage begins.","Drag vertically anywhere to move the glowing shield along the wall.","Catch the returning blade with your shield. A miss ends the run.","Drones have three health units; each blade or minigun hit removes one third.","The two miniguns rotate toward different enemies and fire automatically.","Survive every wave to clear a stage. New miniguns unlock after each world.","Hold a second touch to slow time. Tap NOVA to trigger the purchased pulse.","Easy gives a larger shield. Hard makes the blade faster and shield smaller.");lines.forEachIndexed{i,s->text(s,0.5,0.25+i*0.061,0.017,"#e5edf9","center",w*0.91)};button("BACK",0.24,0.80,0.76,0.88,gold())}
private fun drawShop(){background(true);text("BLADE SHOP",0.5,0.105,0.052,"#ffffff","center");text("COINS: "+coins,0.5,0.17,0.023,gold(),"center");upgrades.forEachIndexed{i,item->val b=card(i);val x=b[0]*w;val y=b[1]*h;val bw=(b[2]-b[0])*w;val bh=(b[3]-b[1])*h;val lvl=upgradeLevel(item.id).coerceAtMost(item.max);val locked=item.id=="pulse_core"&&upgradeLevel("nova")==0;drawAsset("UI Elements/UI Panel.png",x,y,bw,bh,0.62);rect(x,y,bw,bh,dark(),0.44,m*0.012,if(i%3==0)cyan()else if(i%3==1)gold()else pink());text(item.title,(b[0]+b[2])/2,b[1]+0.040,0.018,"#ffffff","center",bw*0.94);drawAsset(item.icon,x+bw*0.36,y+bh*0.20,bw*0.28,bh*0.40,if(locked)0.25 else 1.0);text(item.description,(b[0]+b[2])/2,b[1]+0.142,0.012,muted(),"center",bw*0.94);val status=when{locked->"UNLOCK NOVA FIRST";lvl>=item.max->"MAX LEVEL • "+lvl;else->"LV "+lvl+" → "+(lvl+1)+" • "+cost(item)+" COINS"};text(status,(b[0]+b[2])/2,b[1]+0.183,0.012,if(locked)muted()else if(lvl>=item.max)cyan()else gold(),"center",bw*0.96);if(locked)rect(x,y,bw,bh,"#000000",0.3,m*0.012)};button(if(shopReturn=="playing")"BACK TO BATTLE"else"BACK TO MENU",0.24,0.805,0.76,0.895,cyan());text("PERMANENT UPGRADES ARE SAVED IN THIS BROWSER",0.5,0.945,0.014,muted(),"center")}
private fun drawComplete(){background(true);drawCover("Backgrounds & Environments/Victory Background.png",0.0,0.0,w,h,0.84);drawAsset("Banners & Text/Victory Banner.png",w*0.16,h*0.24,w*0.68,h*0.18);text("You conquered all ten worlds.",0.5,0.49,0.026,"#ffffff","center");button("PLAY AGAIN",0.15,0.565,0.85,0.665,cyan());button("LEVEL SELECT",0.15,0.68,0.85,0.78,gold())}
private fun draw(){g.fillStyle=dark();g.fillRect(0.0,0.0,w,h);when(screen){"menu"->drawMenu();"difficulty"->drawDifficulty();"worlds"->drawWorlds();"levels"->drawLevels();"playing"->drawGame();"paused"->drawPaused();"won"->drawWon();"failed"->drawFailed();"campaign_complete"->drawComplete();"story"->drawStory();"features"->drawFeatures();"modes"->drawModes();"customize"->drawCustomize();"miniguns"->drawMiniguns();"settings"->drawSettings();"help"->drawHelp();"shop"->drawShop()};if(screen!="playing"&&messageTime>0&&messageText.isNotBlank())text(messageText,0.5,0.965,0.015,gold(),"center")}
private fun update(dtRaw:Double){val dt=dtRaw.coerceIn(0.0,0.04);animationTime+=dt;messageTime=max(0.0,messageTime-dt);impactTime=max(0.0,impactTime-dt);novaFlash=max(0.0,novaFlash-dt);novaCooldown=max(0.0,novaCooldown-dt);teleportCooldown=max(0.0,teleportCooldown-dt);for((k,v) in effects.toMap()){val n=max(0.0,v-dt);if(n==0.0)effects.remove(k)else effects[k]=n};particles.forEach{p->p.life-=dt;p.x+=p.vx*dt;p.y+=p.vy*dt;p.vx*=0.985;p.vy*=0.985};particles.removeAll{it.life<=0};enemies.forEach{it.hitCooldown=max(0.0,it.hitCooldown-dt)};if(screen!="playing"){if(!slow)slowMeter=min(1.0,slowMeter+dt*0.04);return};elapsed+=dt;if(mode=="time_attack"&&elapsed>=60){fail("TIME ATTACK OVER — 60 SECONDS");return};comboWindow=max(0.0,comboWindow-dt);if(comboWindow<=0)combo=0;val factor=if((slow&&slowMeter>0)||(effects["slow_time"]?:0.0)>0)0.28 else 1.0;if(slow&&slowMeter>0)slowMeter=max(0.0,slowMeter-dt*0.20)else slowMeter=min(1.0,slowMeter+dt*0.075);updateEnemies(dt*factor);if(screen!="playing")return;updateGuns(dt*factor);if(flying)repeat(3){if(screen=="playing"&&flying)simulateStep(dt*factor/3.0)};if(enemies.none{it.alive}&&screen=="playing")complete()}
private fun resize(){val dpr=min(2.0,window.devicePixelRatio);val r=canvas.getBoundingClientRect();w=max(320.0,r.width);h=max(240.0,r.height);m=min(w,h);canvas.width=(w*dpr).toInt();canvas.height=(h*dpr).toInt();g.setTransform(dpr,0.0,0.0,dpr,0.0,0.0)}
private fun frame(ts:Double){if(lastFrame==0.0)lastFrame=ts;val dt=((ts-lastFrame)/1000.0).coerceIn(0.0,0.04);lastFrame=ts;update(dt);draw();setMusic();window.requestAnimationFrame(::frame)}
private fun installInput(){
    canvas.asDynamic().addEventListener("pointerdown",{e:dynamic->val r=canvas.getBoundingClientRect();val x=((e.clientX as Number).toDouble()-r.left)/w;val y=((e.clientY as Number).toDouble()-r.top)/h;val id=(e.pointerId as Number).toInt();pointers[id]=Pair(x,y);try{canvas.asDynamic().setPointerCapture(id)}catch(_:Throwable){}
        if(screen!="playing"){sfx("UI & Feedback SFX/Button Click.wav");tap(x,y)}else{val pause=if(leftHanded)inside(x,y,0.03,0.027,0.175,0.11)else inside(x,y,0.825,0.027,0.97,0.11);if(pause){screen="paused";slow=false}else if(inside(x,y,0.82,0.83,0.97,0.94)){if(upgradeLevel("nova")>0)nova()else openShop("playing")}else{if(primaryPointer<0){primaryPointer=id;guardY=clampGuard(y)};if(pointers.size>=2)slow=true}};setMusic()})
    canvas.asDynamic().addEventListener("pointermove",{e:dynamic->val id=(e.pointerId as Number).toInt();if(!pointers.containsKey(id))return@addEventListener;val r=canvas.getBoundingClientRect();val x=((e.clientX as Number).toDouble()-r.left)/w;val y=((e.clientY as Number).toDouble()-r.top)/h;pointers[id]=Pair(x,y);if(screen=="playing"){if(id==primaryPointer)guardY=clampGuard(y);slow=pointers.size>=2}})
    fun release(e:dynamic){val id=(e.pointerId as Number).toInt();pointers.remove(id);if(id==primaryPointer)primaryPointer=pointers.keys.firstOrNull()?:-1;slow=pointers.size>=2}
    canvas.asDynamic().addEventListener("pointerup",{e:dynamic->release(e)});canvas.asDynamic().addEventListener("pointercancel",{e:dynamic->release(e)})
    window.addEventListener("keydown",{e:dynamic->val key=(e.key as? String)?:"";when(key){"Escape"," "->{if(screen=="playing")screen="paused"else if(screen=="paused")screen="playing"else back()};"ArrowUp"->{if(screen=="playing")guardY=clampGuard(guardY-0.045)};"ArrowDown"->{if(screen=="playing")guardY=clampGuard(guardY+0.045)};"n","N","e","E"->{if(screen=="playing")nova()}};if(key==" "||key.startsWith("Arrow"))e.preventDefault()})
}
fun main(){canvas=document.getElementById("game") as HTMLCanvasElement;g=canvas.getContext("2d") as CanvasRenderingContext2D;unlocked=intPref("unlocked_level",1).coerceIn(1,TOTAL);coins=intPref("coins",0).coerceAtLeast(0);difficulty=intPref("difficulty_stars",2).coerceIn(1,3);theme=intPref("theme_id",0).coerceIn(0,5);selectedGun=intPref("player_minigun",0).coerceIn(0,9);leftHanded=boolPref("left_handed",false);sound=boolPref("sound_enabled",true);reducedMotion=boolPref("reduced_motion",false);dynamicDifficulty=boolPref("dynamic_difficulty",true);mode=pref("game_mode","campaign");readStageData();resize();window.addEventListener("resize",{resize()});installInput();spawn(1);screen="menu";window.requestAnimationFrame(::frame)}
